package com.whippahh.progressscape;

import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.GridLayout;

public class ProgressScapePanel extends PluginPanel
{
    private final JLabel statusLabel;
    private final ProgressScapePlugin plugin;

    public ProgressScapePanel(ProgressScapePlugin plugin)
    {
        this.plugin = plugin;
        setLayout(new BorderLayout(0, 8));
        setBorder(new EmptyBorder(10, 10, 10, 10));

        // Title
        JLabel title = new JLabel("ProgressScape");
        title.setFont(new Font("RuneScape Bold", Font.BOLD, 16));
        title.setForeground(new Color(200, 150, 50));
        add(title, BorderLayout.NORTH);

        // Centre panel — button + link stacked
        JPanel centrePanel = new JPanel(new GridLayout(2, 1, 0, 6));
        centrePanel.setOpaque(false);

        JButton syncButton = new JButton("Sync Collection Log");
        syncButton.setToolTipText("Open your Collection Log in-game, then click this");
        syncButton.addActionListener(e -> plugin.syncNowOnClientThread(true));
        centrePanel.add(syncButton);

        JLabel websiteLink = new JLabel("<html><a href=''>progressscape.net</a></html>");
        websiteLink.setFont(new Font("Arial", Font.PLAIN, 11));
        websiteLink.setCursor(new Cursor(Cursor.HAND_CURSOR));
        websiteLink.setToolTipText("Open ProgressScape website");
        websiteLink.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e)
            {
                LinkBrowser.browse("https://progressscape.net");
            }
        });
        centrePanel.add(websiteLink);

        add(centrePanel, BorderLayout.CENTER);

        // Status label
        statusLabel = new JLabel("Ready");
        statusLabel.setFont(new Font("Arial", Font.PLAIN, 11));
        statusLabel.setForeground(Color.GRAY);
        add(statusLabel, BorderLayout.SOUTH);
    }

    public void setStatus(String message)
    {
        SwingUtilities.invokeLater(() -> statusLabel.setText(message));
    }
}

package com.whippahh.progressscape;

import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import java.awt.image.BufferedImage;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@PluginDescriptor(
		name = "ProgressScape",
		description = "Syncs your quests, diaries, boss KC and collection log to ProgressScape",
		tags = {"progressscape", "quests", "diaries", "bosses", "sync"}
)
public class ProgressScapePlugin extends Plugin
{
	private static final Pattern KC_PATTERN =
			Pattern.compile("Your (.+) kill count is: (\\d+)\\.");

	// ── Collection log full-scan trick ──────────────────────────────────
	// Borrowed from the (open-source) WikiSync plugin: the game only ever
	// builds a collection log item slot's widget for the category currently
	// on screen, one at a time — UNLESS you trigger the log's own built-in
	// search-all feature, which briefly renders every obtained item across
	// every category in one burst. clientscript 4100 fires once per item as
	// it's built during that burst (and only for items actually obtained —
	// locked slots use a different, simpler build path that never invokes
	// it), so listening for it during the burst gives us the full log in
	// one click instead of requiring the user to open every category.
	private static final int COLLECTION_LOG_GROUP_ID = 621;
	private static final int COLLECTION_LOG_SEARCH_TOGGLE_CHILD = 76;
	private static final int COLLECTION_LOG_SEARCH_SCRIPT_ID = 2240;
	private static final int COLLECTION_LOG_ITEM_SCRIPT_ID = 4100;
	private static final int COLLECTION_LOG_SYNC_DELAY_TICKS = 5;

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SyncService syncService;

	@Inject
	private ClientThread clientThread;

	private ProgressScapePanel panel;
	private NavigationButton navButton;
	private boolean pendingLoginSync = false;
	// GameState.LOGGED_IN does NOT only fire at login — it fires again after
	// every world hop and every region load. Syncing on each one rewrote the
	// player's entire row (all quests, all diaries, every CA, every boss KC)
	// dozens of times a session, which was consuming the database's disk IO
	// budget. This gates it to one sync per actual login.
	private boolean syncedThisLogin = false;
	private int collectionLogSyncCountdown = -1;

	@Override
	protected void startUp() throws Exception
	{
		panel = new ProgressScapePanel(this);
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		navButton = NavigationButton.builder()
				.tooltip("ProgressScape")
				.icon(icon)
				.priority(5)
				.panel(panel)
				.build();
		clientToolbar.addNavigation(navButton);
		log.debug("ProgressScape started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		log.debug("ProgressScape stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			if (!syncedThisLogin)
			{
				pendingLoginSync = true;
			}
			else
			{
				// Makes the gate visible in the log — otherwise a suppressed
				// hop is indistinguishable from the event never firing.
				log.debug("ProgressScape: already synced this login, skipping (world hop or region load)");
			}
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// Reaching the login screen is the only reliable "really logged
			// out" signal — a world hop never passes through it — so this is
			// where the per-login state gets reset.
			//
			// The syncNow(false) that used to be here was dead code: syncNow
			// returns immediately unless the game state is LOGGED_IN, and by
			// definition it isn't here. It never uploaded anything.
			syncedThisLogin = false;
			syncService.clearKCs();
			// Captured collection log items are per-account. Without this,
			// hopping to an alt in the same client session uploaded the
			// previous account's collection log under the alt's name.
			syncService.clearCollectionLog();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (pendingLoginSync)
		{
			pendingLoginSync = false;
			syncedThisLogin = true;
			syncNow(false);
		}

		if (collectionLogSyncCountdown > 0)
		{
			collectionLogSyncCountdown--;
			if (collectionLogSyncCountdown == 0)
			{
				syncNow(true);
			}
		}
	}

	/**
	 * Fires once per collection log item slot as the game builds it. Only
	 * obtained items take this script path, so anything seen here is a
	 * confirmed obtained item — this is what actually populates the synced
	 * list, whether triggered by {@link #startCollectionLogSync()}'s search
	 * burst or just by the player naturally browsing their log.
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != COLLECTION_LOG_ITEM_SCRIPT_ID) return;
		Object[] args = event.getScriptEvent().getArguments();
		if (args == null || args.length < 2 || !(args[1] instanceof Integer)) return;
		int itemId = (Integer) args[1];
		ItemComposition comp = client.getItemDefinition(itemId);
		if (comp == null) return;
		syncService.recordCollectionLogItem(comp.getName());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE) return;
		String message = event.getMessage();
		Matcher matcher = KC_PATTERN.matcher(message);
		if (matcher.matches())
		{
			String bossName = matcher.group(1);
			int kc = Integer.parseInt(matcher.group(2));
			syncService.updateBossKC(bossName, kc);
			log.debug("KC captured: {} = {}", bossName, kc);
		}
	}

	/**
	 * Entry point for syncs triggered from outside the client thread (e.g. a Swing
	 * button click on the plugin panel). RuneLite requires Client/Widget access to
	 * happen on the client thread, so this hands the work off via ClientThread
	 * instead of touching client state directly from the calling (EDT) thread.
	 */
	public void syncNowOnClientThread(boolean includeCollectionLog)
	{
		clientThread.invoke(() -> {
			if (includeCollectionLog)
			{
				startCollectionLogSync();
			}
			else
			{
				syncNow(false);
			}
		});
	}

	/**
	 * Forces the collection log's built-in search-all to fire (see the block
	 * comment above the COLLECTION_LOG_* constants), then waits a few ticks
	 * for the resulting render burst — and the item captures it triggers —
	 * to finish before actually sending the sync via {@link #syncNow}.
	 */
	private void startCollectionLogSync()
	{
		Widget frame = client.getWidget(COLLECTION_LOG_GROUP_ID, 0);
		if (frame == null || frame.isHidden())
		{
			panel.setStatus("Open your Collection Log first!");
			return;
		}
		panel.setStatus("Scanning collection log...");
		int searchToggleWidgetId = (COLLECTION_LOG_GROUP_ID << 16) | COLLECTION_LOG_SEARCH_TOGGLE_CHILD;
		client.menuAction(-1, searchToggleWidgetId, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(COLLECTION_LOG_SEARCH_SCRIPT_ID);
		collectionLogSyncCountdown = COLLECTION_LOG_SYNC_DELAY_TICKS;
	}

	public void syncNow(boolean includeCollectionLog)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			panel.setStatus("Not logged in");
			return;
		}
		Player local = client.getLocalPlayer();
		if (local == null) return;
		String username = local.getName();
		if (username == null || username.isEmpty()) return;
		panel.setStatus("Syncing...");
		syncService.sync(username, includeCollectionLog, client, panel);
	}
}

package com.whippahh.progressscape;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Varbits;
import net.runelite.api.gameval.VarPlayerID;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.net.URLEncoder;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@Slf4j
@Singleton
public class SyncService
{
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final String SUPABASE_URL = "https://hbfnvijfjboxhamjmlhm.supabase.co";
    private static final String SUPABASE_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImhiZm52aWpmamJveGhhbWptbGhtIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM0NjcwNDYsImV4cCI6MjA4OTA0MzA0Nn0.wg9Ho_rZBXqH7ulFkT4p1pAamC5bpBDTRXI75_rCPAY";

    private static final int ACCOUNT_TYPE_VARPLAYER = 1777;

    // ── Combat Achievements ─────────────────────────────────────────────
    // Completion is stored as one bit per task across 20 sequential
    // VarPlayers, 32 tasks per varp. The bit a task uses is NOT its position
    // in any list we maintain — it is an id Jagex stores on that task's
    // struct in the game cache (param 1306).
    //
    // The previous implementation assumed a hand-authored 637-entry enum's
    // declaration order matched those ids. It doesn't, so completions were
    // read from the wrong bits — which is why e.g. Barrows tasks came back
    // missing despite being done.
    //
    // Instead, walk the game's own per-tier enums (each lists that tier's
    // task struct ids) and read the real id and name straight off each
    // struct. No hand-maintained task list, no ordering assumption, and new
    // tasks Jagex adds are picked up without a plugin update. Approach
    // confirmed against the open-source cdfisher/ca-export plugin.
    //
    // Must run on the client thread — sync() is already called from there.
    private static final int[] CA_TIER_ENUMS = { 3981, 3982, 3983, 3984, 3985, 3986 };
    private static final int CA_PARAM_TASK_ID = 1306;
    private static final int CA_PARAM_TASK_NAME = 1308;
    private static final int[] CA_TASK_VARPS = {
            VarPlayerID.CA_TASK_COMPLETED_0,  VarPlayerID.CA_TASK_COMPLETED_1,
            VarPlayerID.CA_TASK_COMPLETED_2,  VarPlayerID.CA_TASK_COMPLETED_3,
            VarPlayerID.CA_TASK_COMPLETED_4,  VarPlayerID.CA_TASK_COMPLETED_5,
            VarPlayerID.CA_TASK_COMPLETED_6,  VarPlayerID.CA_TASK_COMPLETED_7,
            VarPlayerID.CA_TASK_COMPLETED_8,  VarPlayerID.CA_TASK_COMPLETED_9,
            VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
            VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13,
            VarPlayerID.CA_TASK_COMPLETED_14, VarPlayerID.CA_TASK_COMPLETED_15,
            VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
            VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19,
    };

    // Same public endpoint RuneLite's own Hiscore panel queries. Gives full
    // lifetime KC for every ranked boss in one request — no session/chat
    // message limitation like the old bossKCs-only approach had.
    private static final String HISCORE_URL = "https://secure.runescape.com/m=hiscore_oldschool/index_lite.json";

    @Inject
    private OkHttpClient httpClient;

    @Inject
    private Gson gson;

    private final Map<String, Integer> bossKCs = new HashMap<>();

    // Populated by ProgressScapePlugin's clientscript-4100 listener as
    // collection log item slots get built (whether from natural browsing or
    // the search-all burst triggered by the Sync button). Never cleared, so
    // it only grows across the client session — repeated syncs accumulate.
    private final Set<String> collectionLogObtained = ConcurrentHashMap.newKeySet();

    private final ExecutorService executor = Executors.newSingleThreadExecutor();

    // The exact JSON last accepted by the players table. Each upsert rewrites
    // every column — all quests, all diaries, every CA name, every boss KC —
    // so an unchanged re-send costs a full row rewrite, a dead tuple, TOAST
    // churn and the autovacuum to clean it up, for nothing. Most syncs send
    // byte-identical data, so comparing first skips the write entirely.
    private String lastPlayersPayload = null;

    public void updateBossKC(String bossName, int kc)
    {
        bossKCs.put(bossName, kc);
        log.debug("KC updated: {} = {}", bossName, kc);
    }

    public void clearKCs()
    {
        bossKCs.clear();
    }

    /** Called on logout — captured items belong to the account that was logged in. */
    public void clearCollectionLog()
    {
        collectionLogObtained.clear();
    }

    public void recordCollectionLogItem(String rawName)
    {
        if (rawName == null || rawName.isEmpty()) return;
        String clean = rawName.replaceAll("<[^>]+>", "").trim();
        if (clean.isEmpty()) return;
        if (collectionLogObtained.add(clean))
        {
            log.debug("Collection log item captured: {}", clean);
        }
    }

    public void sync(String username, boolean includeCollectionLog,
                     Client client, ProgressScapePanel panel)
    {
        JsonObject quests = new JsonObject();
        for (Quest quest : Quest.values())
        {
            QuestState state = quest.getState(client);
            quests.addProperty(quest.getName(), state.name());
        }

        JsonObject diaries = buildDiaries(client);

        JsonArray caCompleted = buildCombatAchievements(client);

        // Snapshot of this-session live chat captures. The full boss list is
        // actually built on the background thread in sendToSupabase(), merged
        // with a hiscores lookup — see the comment there for why.
        Map<String, Integer> bossKCSnapshot = new HashMap<>(bossKCs);

        JsonObject collectionLog = null;
        if (includeCollectionLog)
        {
            if (collectionLogObtained.isEmpty())
            {
                panel.setStatus("No collection log items captured — try again");
                return;
            }
            JsonArray obtained = new JsonArray();
            for (String name : collectionLogObtained)
            {
                obtained.add(name);
            }
            collectionLog = new JsonObject();
            collectionLog.add("All", obtained);
        }

        int accountTypeId = client.getVarpValue(ACCOUNT_TYPE_VARPLAYER);
        String accountType = accountTypeFromId(accountTypeId);

        JsonObject payload = new JsonObject();
        payload.addProperty("username", username);
        payload.addProperty("account_type", accountType);
        payload.add("quests", quests);
        payload.add("diaries", diaries);
        payload.add("ca_completed", caCompleted);
        // NOTE: "bosses" is intentionally not added here — sendToSupabase
        // adds it after merging a hiscores lookup (a network call, so it
        // belongs on the background thread) with bossKCSnapshot.

        final JsonObject finalCL = collectionLog;
        executor.submit(() -> sendToSupabase(payload, finalCL, bossKCSnapshot, panel));
    }

    private void sendToSupabase(JsonObject payload, JsonObject collectionLog,
                                Map<String, Integer> bossKCSnapshot, ProgressScapePanel panel)
    {
        try
        {
            String username = payload.get("username").getAsString();

            // Hiscores gives full lifetime KC for every ranked boss — the
            // same public endpoint RuneLite's own Hiscore panel uses. Live
            // in-session chat captures are merged on top since they can be
            // fresher than hiscores, which lags behind by several minutes.
            JsonObject bosses = fetchHiscoreBosses(username);
            for (Map.Entry<String, Integer> entry : bossKCSnapshot.entrySet())
            {
                bosses.addProperty(entry.getKey(), entry.getValue());
            }
            payload.add("bosses", bosses);

            String payloadJson = gson.toJson(payload);
            boolean playersUnchanged = payloadJson.equals(lastPlayersPayload);

            if (playersUnchanged && collectionLog == null)
            {
                // Nothing to say and nothing else to send — don't touch the DB.
                log.debug("ProgressScape: player data unchanged, skipping write");
                panel.setStatus("Already up to date");
                return;
            }

            if (!playersUnchanged)
            {
                Request playerRequest = new Request.Builder()
                        .url(SUPABASE_URL + "/rest/v1/players?on_conflict=username")
                        .header("apikey", SUPABASE_KEY)
                        .header("Authorization", "Bearer " + SUPABASE_KEY)
                        .header("Content-Type", "application/json")
                        .header("Prefer", "resolution=merge-duplicates")
                        .post(RequestBody.create(JSON, payloadJson))
                        .build();

                try (Response response = httpClient.newCall(playerRequest).execute())
                {
                    if (!response.isSuccessful())
                    {
                        log.warn("ProgressScape player sync failed: {}", response.code());
                        panel.setStatus("Sync failed (" + response.code() + ")");
                        return;
                    }
                }
                // Only remember it once the server has actually accepted it.
                lastPlayersPayload = payloadJson;
            }

            if (collectionLog != null)
            {
                JsonObject clPayload = new JsonObject();
                clPayload.addProperty("username", username);
                clPayload.add("log_data", collectionLog);

                Request clRequest = new Request.Builder()
                        .url(SUPABASE_URL + "/rest/v1/collection_log?on_conflict=username")
                        .header("apikey", SUPABASE_KEY)
                        .header("Authorization", "Bearer " + SUPABASE_KEY)
                        .header("Content-Type", "application/json")
                        .header("Prefer", "resolution=merge-duplicates")
                        .post(RequestBody.create(JSON, gson.toJson(clPayload)))
                        .build();

                try (Response response = httpClient.newCall(clRequest).execute())
                {
                    if (!response.isSuccessful())
                    {
                        log.warn("Collection log sync failed: {}", response.code());
                        panel.setStatus("Collection log failed (" + response.code() + ")");
                        return;
                    }
                }
                panel.setStatus("Collection log synced! (" + collectionLogObtained.size() + " items)");
            }
            else
            {
                panel.setStatus("Synced!");
            }

            log.debug("ProgressScape sync OK for {}", username);
        }
        catch (IOException e)
        {
            log.warn("ProgressScape sync error", e);
            panel.setStatus("Sync error — check connection");
        }
    }

    /**
     * Queries the public OSRS hiscores (the same endpoint RuneLite's own
     * Hiscore panel uses) for every ranked activity's score. This includes
     * bosses and raids, but also clue scrolls, minigames, league points etc.
     * — we don't filter those out here; the website only acts on names it
     * recognizes as bosses, so any extra non-boss entries are harmless.
     */
    private JsonObject fetchHiscoreBosses(String username)
    {
        JsonObject bosses = new JsonObject();
        try
        {
            String url = HISCORE_URL + "?player=" + URLEncoder.encode(username, "UTF-8");
            Request request = new Request.Builder().url(url).build();
            try (Response response = httpClient.newCall(request).execute())
            {
                if (!response.isSuccessful() || response.body() == null)
                {
                    log.debug("Hiscore lookup failed for {}: {}", username, response.code());
                    return bosses;
                }
                JsonObject root = gson.fromJson(response.body().string(), JsonObject.class);
                JsonArray activities = (root != null) ? root.getAsJsonArray("activities") : null;
                if (activities == null) return bosses;

                for (JsonElement el : activities)
                {
                    JsonObject activity = el.getAsJsonObject();
                    String name = activity.get("name").getAsString();
                    int score = activity.get("score").getAsInt();
                    // score is -1 when unranked (never done, or below the
                    // hiscore cutoff) — only forward entries actually ranked.
                    if (score >= 0)
                    {
                        bosses.addProperty(name, score);
                    }
                }
            }
        }
        catch (Exception e)
        {
            log.warn("Hiscore boss lookup failed for {}", username, e);
        }
        return bosses;
    }

    private JsonArray buildCombatAchievements(Client client)
    {
        JsonArray completed = new JsonArray();
        for (int enumId : CA_TIER_ENUMS)
        {
            var tierEnum = client.getEnum(enumId);
            if (tierEnum == null) continue;

            for (int structId : tierEnum.getIntVals())
            {
                var struct = client.getStructComposition(structId);
                if (struct == null) continue;

                String name = struct.getStringValue(CA_PARAM_TASK_NAME);
                if (name == null || name.isEmpty()) continue;

                // The task's real bit index, straight from the cache.
                int id = struct.getIntValue(CA_PARAM_TASK_ID);
                if (id < 0) continue;

                int varpIndex = id / 32;
                if (varpIndex >= CA_TASK_VARPS.length) continue;

                if ((client.getVarpValue(CA_TASK_VARPS[varpIndex]) & (1 << (id % 32))) != 0)
                {
                    completed.add(name);
                }
            }
        }
        return completed;
    }

    private JsonObject buildDiaries(Client client)
    {
        JsonObject diaries = new JsonObject();

        int[][] diaryVarbits = {
                { Varbits.DIARY_ARDOUGNE_EASY,   Varbits.DIARY_ARDOUGNE_MEDIUM,   Varbits.DIARY_ARDOUGNE_HARD,   Varbits.DIARY_ARDOUGNE_ELITE },
                { Varbits.DIARY_DESERT_EASY,     Varbits.DIARY_DESERT_MEDIUM,     Varbits.DIARY_DESERT_HARD,     Varbits.DIARY_DESERT_ELITE },
